script:
 frappe.ui.form.on('Task', {
  refresh: function(frm) {
    if (frm.doc.confirm) {
      if (frm.doc.owner === frappe.session.user) {
        frm.set_df_property('status', 'options', 'Open\nCompleted');
      } else {
        frm.set_df_property('status', 'options', 'Open\nWorking\nPending Review');
      }
    } else {
      if (frm.doc.owner === frappe.session.user) {
        frm.set_df_property('status', 'options', 'Open\nWorking\nPending Review\nOverdue\nTemplate\nCompleted\nCancelled');
      } else {
        frm.set_df_property('status', 'options', 'Open\nWorking\nPending Review\nOverdue\nTemplate\nCompleted\nCancelled');
      }
    }
  }
});

frappe.ui.form.on("Task", "onload", function(frm) {
    // Проверяем, является ли текущий пользователь владельцем задачи
    if (frappe.session.user !== frm.doc.owner) {
        // Проверяем, имеет ли текущий пользователь роль Dinext_Project_Manager
        if (frappe.user.has_role("Dinext_Project_Manager")) {
            // Если роль есть, разрешаем редактирование кнопки "confirm"
            frm.toggle_enable("confirm", true);
        } else {
            // Если роли нет, отключаем кнопку "confirm"
            frm.toggle_enable("confirm", false);
        }
    } else {
        // Если текущий пользователь является владельцем, разрешаем редактирование
        frm.toggle_enable("confirm", true);
    }
});

frappe.ui.form.on('Task', {
    refresh(frm) {
        // Проверяем, есть ли у пользователя роль "Dinext_Project_Manager"
        if (!frappe.user.has_role("Dinext_Project_Manager")) {
            console.log("User does not have role: Dinext_Project_Manager");
            // Скрываем поле custom_project_team
            frm.set_df_property('custom_include', 'read_only', 1);
        } else {
            console.log("User has role: Dinext_Project_Manager");
            // Показываем поле custom_project_team, если у пользователя есть роль
            frm.set_df_property('custom_include', 'read_only', 0);
        }
    }
});

frappe.ui.form.on("Issue", {
  status: function(frm) {
    if (["Open", "Replied", "On Hold"].includes(frm.doc.status)) {
      frm.toggle_display("resolution_date", false);
     } else if (frm.doc.status === "Resolved") {
      frm.toggle_display("resolution_date", true);
      frm.set_value("resolution_date", frappe.datetime.now_datetime());
     }  
  }
});

frappe.ui.form.on("Project", {
    validate: function(frm) {
        var duplicateFound = false;
        var participants = {};

        frm.doc.custom_ts_details.forEach(function(row) {
            var key = row.pt_role + "_" + row.pt_participant;
            if (participants[key]) {
                var existingRow = participants[key];
                // Проверяем пересечение периодов действия
                if ((row.pt_valid_from && row.pt_valid_for) &&
                    (existingRow.pt_valid_from && existingRow.pt_valid_for) &&
                    ((row.pt_valid_from >= existingRow.pt_valid_from && row.pt_valid_from <= existingRow.pt_valid_for) ||
                    (row.pt_valid_for >= existingRow.pt_valid_from && row.pt_valid_for <= existingRow.pt_valid_for))) {
                    duplicateFound = true;
                    return false; // break the loop
                } else if (!row.pt_valid_from || !row.pt_valid_for) {
                    frappe.msgprint(__("Внимание! В проектной команде обнаружен дублирующий участник или группа. Если это не ошибка, укажите для дублей разные периоды действия"));
                    frappe.validated = false;
                }
            }
            participants[key] = {
                pt_valid_from: row.pt_valid_from,
                pt_valid_for: row.pt_valid_for
            };
        });

        if (duplicateFound) {
            frappe.msgprint(__("Внимание! В вашей проектной команде уже есть участник или группа с этой ролью и периодом действия"));
            frappe.validated = false;
        }
    }
});

frappe.ui.form.on("Project", "onload", function(frm) {
    frappe.model.with_doctype("Project Role", function() {
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Project Role",
                filters: { sole__participant: 1 },
                fields: ["role_name"]
            },
            callback: function(response) {
                if (response.message) {
                    var soleParticipantRoles = response.message.map(function(role) {
                        return role.role_name;
                    });
                    console.log(soleParticipantRoles);

                    frm.set_query("pt_participant_type", "custom_ts_details", function(doc, cdt, cdn) {
                        var row = locals[cdt][cdn];
                        if (row.pt_role && soleParticipantRoles.includes(row.pt_role)) {
                            return {
                                filters: [
                                    ["DocType", "name", "in", ["User"]]
                                ]
                            };
                        } else {
                            return {
                                filters: [
                                    ["DocType","name", "in", ["User", "User Group", "Role"]]
                                ]
                            };
                        }
                    });
                }
            }
        });
    });
});





frappe.ui.form.on("Project", {
    validate: function(frm) {
        if (frm.doc.custom_ts_details) {
            for (var i = 0; i < frm.doc.custom_ts_details.length; i++) {
                var row = frm.doc.custom_ts_details[i];
                if (row.pt_valid_from && row.pt_valid_for && row.pt_valid_for < row.pt_valid_from) {
                    frappe.msgprint(__("Дата окончания периода действия не может быть раньше его начала"));
                    frappe.validated = false;
                    return;
                }
            }
        }
    }
});


frappe.ui.form.on("Project", {
    validate: function(frm) {
        frappe.model.with_doctype("Project Role", function() {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Project Role",
                    filters: { mandatory_participant: 1 },
                    fields: ["role_name"]
                },
                callback: function(response) {
                    if (response.message) {
                        var mandatoryRoles = response.message.map(function(role) {
                            return role.role_name;
                        });

                        var missingRoles = [];
                        // Проверяем таблицу наличия всех обязательных ролей
                        $.each(mandatoryRoles, function(index, role) {
                            var roleFound = false;
                            $.each(frm.doc.custom_ts_details, function(index, row) {
                                if (row.pt_role && row.pt_role === role) {
                                    roleFound = true;
                                }
                            });
                            if (!roleFound) {
                                missingRoles.push(role);
                            }
                        });

                        // Выводим сообщение об ошибке, если отсутствуют обязательные роли
                        if (missingRoles.length > 0) {
                            frappe.msgprint(__("В команде проекта отсутствуют обязательные роли: {0}", [missingRoles.join(", ")]));
                            frappe.validated = false;
                        }
                    }
                }
            });
        });
    }
});

frappe.ui.form.on("Project", {
    validate: function(frm) {
        frappe.model.with_doctype("Project Role", function() {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Project Role",
                    filters: { sole__participant: 1 }, 
                    fields: ["role_name"]
                },
                callback: function(response) {
                    if (response.message) {
                        var soleParticipantRoles = response.message.map(function(role) {
                            return role.role_name;
                        });

                        // Проверяем наличие пересечения периодов действия для ролей
var overlappingRoles = [];
var missingValidityPeriodsRoles = [];
$.each(frm.doc.custom_ts_details, function(index, row) {
    if (row.pt_role && soleParticipantRoles.includes(row.pt_role)) {
        var currentRole = row.pt_role;
        var currentValidFrom = row.pt_valid_from;
        var currentValidFor = row.pt_valid_for;

        if (!currentValidFrom && !currentValidFor) {
            missingValidityPeriodsRoles.push(currentRole);
        }

        $.each(frm.doc.custom_ts_details, function(innerIndex, innerRow) {
            if (innerRow.pt_role === currentRole && innerRow.name !== row.name) {
                if ((innerRow.pt_valid_from <= currentValidFor && innerRow.pt_valid_for >= currentValidFrom) ||
                    (currentValidFrom <= innerRow.pt_valid_for && currentValidFor >= innerRow.pt_valid_from)) {
                    if (!overlappingRoles.includes(currentRole)) {
                        overlappingRoles.push(currentRole);
                    }
                }
            }
        });
    }
});

// Выводим сообщение об ошибке при наличии пересекающихся периодов действия у одинаковых ролей с признаком sole__participant
if (overlappingRoles.length > 0) {
    var overlappingRolesString = overlappingRoles.join(", ");
    var message1 = "В команде проекта может быть только одна роль: " + overlappingRolesString + " на определенный период";
    frappe.msgprint(message1);
    frappe.validated = false;
}

// Находим первую повторяющуюся роль
var overlappingRole = missingValidityPeriodsRoles.find(function(role, index) {
    return missingValidityPeriodsRoles.indexOf(role) !== index;
});

// Выводим сообщение об ошибке для ролей с признаком sole__participant, у которых значения периода действия не определено
if (overlappingRole) {
    var message2 = "На проекте может быть только одна роль " + overlappingRole;
    frappe.msgprint(message2);
    frappe.validated = false;
}
                    }
                }
            });
        });
    }
});

frappe.ui.form.on("Project", {
    validate: function(frm) {
        var participants = [];
        var userGroupsProcessed = 0;
        var userGroupCount = frm.doc.custom_ts_details.filter(d => d.pt_participant_type === "User Group").length;

        // Сначала получаем текущих расшаренных пользователей
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "DocShare",
                filters: {
                    share_doctype: "Project",
                    share_name: frm.doc.name
                },
                fields: ["user"]
            },
            callback: function(response) {
                var existingShares = response.message.map(share => share.user);
                
                if (userGroupCount === 0) {
                    processUsers(frm, existingShares);
                } else {
                    processUserGroups(frm, existingShares);
                }
            }
        });
    }
});

function processUsers(frm, existingShares) {
    var participants = [];
    $.each(frm.doc.custom_ts_details, function(i, d) {
        if (d.pt_participant_type === "User") {
            participants.push(d.pt_participant);
        }
    });
    addParticipantsToProject(participants, frm, existingShares);
}

function processUserGroups(frm, existingShares) {
    var participants = [];
    var userGroupsProcessed = 0;
    var userGroupCount = frm.doc.custom_ts_details.filter(d => d.pt_participant_type === "User Group").length;

    $.each(frm.doc.custom_ts_details, function(i, d) {
        if (d.pt_participant_type === "User") {
            participants.push(d.pt_participant);
        }
        if (d.pt_participant_type === "User Group") {
            frappe.call('frappe.client.get', {
                doctype: 'User Group',
                filters: { name: d.pt_participant },
                fieldname: ['user_group_members']
            }).then(function(response) {
                var userGroupMembers = response.message.user_group_members;
                $.each(userGroupMembers, function(index, user) {
                    participants.push(user.user);
                });
                userGroupsProcessed++;
                if (userGroupsProcessed === userGroupCount) {
                    addParticipantsToProject(participants, frm, existingShares);
                }
            });
        }
    });
}

function addParticipantsToProject(participants, frm, existingShares) {
    let uniqueParticipants = [...new Set(participants)]; // Уникальные участники
    
    // Фильтруем только тех, кто еще не расшарен
    let newParticipants = uniqueParticipants.filter(
        participant => !existingShares.includes(participant)
    );

    // Добавляем только новых участников
    newParticipants.forEach(participant => {
        frappe.call({
            method: 'frappe.share.add',
            args: {
                doctype: 'Project',
                name: frm.doc.name,
                user: participant,
                share: 1,
                read: 1
            },
            callback: function(response) {
                if (!response.exc) {
                    frappe.show_alert({
                        message: __("Добавлен доступ для {0}", [participant]),
                        indicator: 'green'
                    }, 3);
                }
            }
        });
    });
    
    // Можно добавить логику для удаления старых шарингов при необходимости
    // removeOldShares(frm, uniqueParticipants, existingShares);
}

