function apply_tree_limit_styles(nodes, results) {
    try {
        // Получаем данные через серверный метод
        nodes.forEach(node => {
            const button = $(`button.plan-fact-button[data-docname='${node.value }'`);
            let status = "no-data";

            let taskData = results.filter( (result) => 
                    result.position == node.value &&
                    ( result.planned_hours > 0 || result.total_hours > 0 )
                );
            
            if ( taskData && taskData.length > 0 ) {
                // Устанавливаем стиль кнопки на основе статуса
                status = get_max_status( taskData );

                // Формируем подсказку
                let tooltip = ( status != "no-data" && status != "no-plan" )
                    ? ( status == "normal"
                        ? __(`Трудозатраты в пределах планов/лимитов`)
                        : __(`Контроль трудозатрат по задаче`) )
                    : __("Не определены плановые трудозатраты");
                
                button.attr('title', tooltip);/**/
                button.off('click').on('click', { node: node, taskData: taskData }, show_plan_fact );
            } 
            
            button.addClass( status );
        });
    } catch (error) {
        console.error('Error updating button style:', error);
    }
}

function get_max_status( positions ) {
    let max_status = "no-data";
    
    for (const data of positions) {
        let status = data.status;
        
        if ( status == 'block' ) {
            return status;
        } else if ( status == 'message' ) {
            max_status = status;
        } else if ( status == 'warning' ) {
            if ( max_status != "message" ) {
                max_status = status;
            }
        } else if ( status == 'normal' ) {
            if ( max_status != "message" && max_status != "warning" ) {
                max_status = status;
            }
        } else {
            if ( max_status == "no-data" ) {
                max_status = status;
            }
        }
    };
    
    return max_status;
}

