frappe.ui.form.on('Project', {
    custom_report(frm) {
        if (!frm.doc.project_name) return;

        // 1. Определяем нужный отчет в зависимости от схемы оплаты
        const report_name = frm.doc.custom_payment_scheme === 'Время и затраты (T&M)' 
            ? 'Контроль ставок по T&M проектам_V2' 
            : 'Контроль ставок по проектам';

        // 2. Открываем отчет
        frappe.set_route('query-report', report_name);

        // 3. Ждем загрузки и имитируем ввод
        const maxAttempts = 10;
        let attempts = 0;
        
        const applyFilter = setInterval(() => {
            attempts++;
            const filterInput = document.querySelector('.dt-filter[data-name="Проект"]');
            
            if (filterInput || attempts >= maxAttempts) {
                clearInterval(applyFilter);
                
                if (filterInput) {
                    // Полностью имитируем ручной ввод
                    simulateUserInput(filterInput, frm.doc.project_name);
                    
                    // Если нужно автоматически применить фильтр
                    const applyBtn = document.querySelector('.dt-apply-filters');
                    if (applyBtn) applyBtn.click();
                }
            }
        }, 300);
    }
});

// Функция для полной имитации пользовательского ввода (без изменений)
function simulateUserInput(element, value) {
    element.focus();
    element.value = value;
    
    const events = ['input', 'change', 'keydown', 'keypress', 'keyup'];
    events.forEach(eventType => {
        const event = new Event(eventType, {
            bubbles: true,
            cancelable: true
        });
        element.dispatchEvent(event);
    });
    
    setTimeout(() => {
        const blurEvent = new Event('blur', { bubbles: true });
        element.dispatchEvent(blurEvent);
    }, 100);
}

// Выносим обработку ответа в отдельную функцию
function handle_copy_positions_response(frm, r) {
    console.log('Full server response:', r); // Для отладки
    
    // Проверяем корректность структуры ответа
    if (!r || !r.message || !r.message.data) {
        console.error('Invalid response structure:', r);
        frappe.show_alert({
            message: __('Некорректный формат ответа от сервера'),
            indicator: 'red'
        }, 5);
        return;
    }

    const result = r.message.data;
    let message = '';
    let indicator = 'orange';

    // Формируем информативное сообщение
    if (result.copied_count > 0) {
        message = __('Успешно скопировано: {0}', [result.copied_count]);
        indicator = 'green';
        
        if (result.duplicates_count > 0 || result.invalid_count > 0) {
            message += '\n'; // Перенос строки
        }
    }
    
    if (result.duplicates_count > 0) {
        message += __('Пропущено дубликатов: {0}', [result.duplicates_count]);
        if (result.invalid_count > 0) {
            message += '\n'; // Перенос строки
        }
    }
    
    if (result.invalid_count > 0) {
        message += __('Пропущено невалидных: {0}', [result.invalid_count]);
    }
    
    if (!message) {
        message = __('Нет позиций для копирования');
    }

    // Показываем уведомление
    frappe.show_alert({
        message: message,
        indicator: indicator
    }, 8);
}

// Функция для обработки ошибок
function handle_copy_positions_error(frm, err) {
    console.error('Request error:', err);
    frappe.show_alert({
        message: __('Ошибка при обработке запроса'),
        indicator: 'red'
    }, 5);
}

function render_copied_positions(frm, positions, customers, fullDates, filteredHolidays) {
    if (!positions || positions.length === 0) return;
    
    positions.forEach(position => {
        position.new = true;
        createNewRow(position, customers, frm, fullDates, filteredHolidays);
    });
    
    loadPositionsTitles( frm.ts_positions );
    timesheetDataUpdated();
}

