function set_parent_task_query(frm) {
  const grid = frm.fields_dict && frm.fields_dict.assignments && frm.fields_dict.assignments.grid;
  if (!grid) return;

  grid.get_field('parent_task').get_query = function (doc, cdt, cdn) {
    // если проект не выбран — ничего не показываем (чтобы не выбрать чужую задачу)
    if (!frm.doc.project) {
      return { filters: { name: ['in', []] } };
    }
    // основной фильтр: только задачи выбранного проекта
    const filters = { project: frm.doc.project };
    // (опционально) если хотите выбирать только родительские (группы), раскомментируйте:
    // filters.is_group = 1;
    // (опционально) исключить отменённые:
    // filters.status = ['!=', 'Cancelled'];

    return { filters };
  };
}

