frappe.ui.form.on('User Delegate', {
    onload: function(frm) {
        console.log('delegate onload');

        frm.delegatable_users = [];

        // Проверяем и устанавливаем права доступа
        set_delegator_permissions(frm);
        
        // Загружаем пользователей для delegator
        load_delegatable_users(frm);
    },

    refresh: function(frm) {
        console.log('delegate refresh');
        
        // При refresh проверяем права
        set_delegator_permissions(frm);
        
        // Настраиваем фильтры для обоих полей
        setup_get_query(frm);
        refresh_get_query(frm);
    },

    delegator: function(frm) {
        if (frm.doc.delegator) {
            frm.set_value('delegate', '');
            console.log(`Замещаемый: ${frm.doc.delegator}`);
            
            // Обновляем фильтр для delegate при изменении delegator
            refresh_get_query(frm);
        }
    },

    validate: function(frm) {
        // 1. Проверка что заместитель и замещаемый не совпадают
        if (frm.doc.delegate && frm.doc.delegator && frm.doc.delegate === frm.doc.delegator) {
            frappe.toast({
                message: __("Заместитель и замещаемый не могут совпадать."),
                indicator: "red"
            });
            frappe.validated = false;
            return;
        }
        
        // 2. Проверка что from_date не раньше текущей даты
        if (frm.doc.from_date) {
            const today = new Date();
            today.setHours(0, 0, 0, 0);
            
            const fromDate = new Date(frm.doc.from_date);
            
            if (fromDate < today) {
                frappe.toast({
                    message: __("Дата начала не может быть раньше текущей даты."),
                    indicator: "red"
                });
                frappe.validated = false;
                return;
            }
        }
        
        // 3. Проверка что to_date не раньше from_date
        if (frm.doc.from_date && frm.doc.to_date) {
            const fromDate = new Date(frm.doc.from_date);
            const toDate = new Date(frm.doc.to_date);
            
            if (toDate < fromDate) {
                frappe.toast({
                    message: __("Дата окончания не может быть раньше даты начала."),
                    indicator: "red"
                });
                frappe.validated = false;
                return;
            }
        }
        
    }
});

// Функция установки прав доступа для delegator
function set_delegator_permissions(frm) {
    const is_system_manager = frappe.user.has_role('System Manager');
    const is_team_lead = frappe.user.has_role('Dinext_Team_Lead');
    
    if (!is_system_manager && !is_team_lead) {
        frm.set_value('delegator', frappe.session.user);
        frm.set_df_property('delegator', 'read_only', 1);
        console.log("Обычный пользователь - delegator заблокирован");
    } else {
        frm.set_df_property('delegator', 'read_only', 0);
        console.log("Системный менеджер или тимлид - delegator доступен");
    }
}

// Функция для загрузки пользователей
function load_delegatable_users(frm) {
    frappe.call({
        method: "getDelegatesByTeamleadReporsTo",
        callback: function(r) {
            if (r.message) {
                frm.delegatable_users = r.message;
                console.log("Loaded delegatable users for delegator:", frm.delegatable_users);
                setup_get_query(frm);
                refresh_get_query(frm);
            }
        }
    });
}

function setup_get_query(frm) {
    const delegator = frm.fields_dict.delegator;
    const delegate = frm.fields_dict.delegate;

    // Для delegator - только пользователи из загруженного списка
    if (delegator && frm.delegatable_users && frm.delegatable_users.length > 0) {
        delegator.get_query = function() {
            return {
                query: "frappe.core.doctype.user.user.user_query",
                filters: {
                    name: ["in", frm.delegatable_users]
                }
            };
        };
    }

    // Для delegate - все пользователи кроме текущего и выбранного delegator
    if (delegate) {
        delegate.get_query = function() {
            let filters = { 
                name: ["!=", frappe.session.user] // Исключаем текущего пользователя
            };
            
            // Если выбран delegator, исключаем и его
            if (frm.doc.delegator) {
                filters.name = ["not in", [frappe.session.user, frm.doc.delegator]];
            }
            
            return {
                query: "frappe.core.doctype.user.user.user_query",
                filters: filters
            };
        };
    }
}

function refresh_get_query(frm) {
    const delegator = frm.fields_dict.delegator;
    const delegate = frm.fields_dict.delegate;

    if (delegator) delegator.refresh();
    if (delegate) delegate.refresh();
}

