/**
 * Отрисовка таблицы «Трудозатраты»
 */
function render_work_efforts_table(frm) {
    if ( frm.last_loaded_project == frm.doc.name && ( new Date() - frm.last_loaded_time ) < 300000 ) {
        console.log("Загружены данные проекта и прошло менее 5 минут..");
        return;
    }

    let wrapper = frm.get_field("custom_work_efforts").$wrapper;
    wrapper.addClass("work_efforts_container");

    wrapper.empty();
    frm.aggregatedTasks = null;

    let controls = $('<div class="work-efforts-controls"></div>').appendTo(wrapper);
    let table_container = $('<div class="work-efforts-table"></div>').appendTo(wrapper);

    controls.append(`
        <button class="btn btn-default" id="we_save_plan">${__('Сохранить план')}</button>
        <button class="btn btn-default" id="toggle_plan">${__("Показать план")}</button>
        <button class="btn btn-default" id="toggle_delta">${__("Показать Δ")}</button>
    `);
    
    addViewOptionsControl(frm, controls);
    let selectedPeriodType = "month";
    let selectedUnit = "hours";
    
    frm.hide_plan = frm.hide_plan || true;
    frm.hide_delta = frm.hide_delta || true;

    controls.find('#we_save_plan').on('click', function() {
        if ( !frm.work_efforts_dt.rowmanager.getCheckedRows()?.length ) {
            frappe.msgprint(__("Выберите задачи, для которых необходимо сохранить плановые данные."));
        } else {
            frappe.confirm(
                __("Вы уверены, что хотите сохранить выбранные прогнозные / фактические данные как плановые?"),
                () => {
                    save_forecast_as_plan(frm);
                },
                () => {
                    frappe.show_alert(__("Операция отменена"), 3);
                }
            );
        }
    });
    
    controls.find('#toggle_plan').on('click', function() {
        frm.hide_plan = !frm.hide_plan;
        $(this).text(frm.hide_plan ? __("Показать план") : __("Скрыть план"));
        updateTable(frm, selectedPeriodType, selectedUnit);
        render_work_efforts_chart(frm);
    });
    
    controls.find('#toggle_delta').on('click', function() {
        frm.hide_delta = !frm.hide_delta;
        $(this).text(frm.hide_delta ? __("Показать Δ") : __("Скрыть Δ"));
        updateTable(frm, selectedPeriodType, selectedUnit);
    });

    function init_table() {
        let columns = get_columns_definition(frm, selectedPeriodType, selectedUnit);

        DataTable.instances = 99;
        frm.work_efforts_dt = new StickyDataTable(table_container[0], {
        //frm.work_efforts_dt = new DataTable(table_container[0], {
            stickyColumnsCount: 4,
            columns: columns,
            data: [],
            inlineFilters: false,
            layout: "fixed",
            logs: true,
            disableReorderColumn: true,
            serialNoColumn: true,
            checkboxColumn: true,
            checkedRowStatus: true,
            dynamicRowHeight: true,
            showTotalRow: true,
            cellHeight: null,
            treeView: true,
            freezeMessage: __("Идет загрузка данных.."),
            
            hooks: {
                columnTotal(columnValues, cell) {
                    if (cell.column.id == "total") {
                        let aggregatedTasks = cur_frm.aggregatedTasks || {};
                        let periods = get_display_periods(cur_frm, cur_frm.currentPeriodType || "month");
                
                        let total_plan = 0;
                        let total_actual = 0;
                        
                        // Вспомогательная рекурсивная функция: возвращает { plan, actual } для заданной задачи и роли за период
                        function sumForTaskByPeriod(taskId, period, planRoles, actualRoles) {
                            let task = aggregatedTasks[taskId];
                            if (!task) return { plan: 0, actual: 0 };
                    
                            // если роль задана — ищем только её запись; иначе — суммируем по всем ролям
                            let plan = 0, actual = 0;
                            let e = (task.role_data || []);
                            
                            if ( e && e.length ) {
                                e.forEach(r => {
                                    const planIndex = planRoles.indexOf(r.role);
                                    const actualIndex = actualRoles.indexOf(r.role);
                                    
                                    if (planIndex > -1) {
                                        let curr_plan = parseFloat(r[`plan_${period.year}_${period.month}`]) || 0;
                                        
                                        if ( curr_plan ) {
                                            plan += curr_plan;
                                            planRoles.splice(planIndex, 1);
                                        }
                                    }
                                    
                                    if (actualIndex > -1) {
                                        let curr_actual = 0;
                                        
                                        if (period.is_past) {
                                            curr_actual = parseFloat(r[`fact_${period.year}_${period.month}`]) || 0;
                                        } else {
                                            curr_actual = parseFloat(r[`forecast_${period.year}_${period.month}`]) || 0;
                                        }
                                        
                                        if ( curr_actual ) {
                                            actual += curr_actual;
                                            actualRoles.splice(actualIndex, 1);
                                        }
                                    }
                                });
                            }
                    
                            // Если явных данных нет — рекурсивно суммируем детей
                            let childTasks = Object.values(aggregatedTasks).filter(t => t.parent_task === taskId);
                            childTasks.forEach(child => {
                                let childPlanRoles = [...planRoles];
                                let childActualRoles = [...actualRoles];
                                if ( !planRoles.length && !actualRoles.length ) return;
                                let r = sumForTaskByPeriod(child.value, period, childPlanRoles, childActualRoles);
                                plan += r.plan;
                                actual += r.actual;
                            });
                            return { plan: plan, actual: actual};
                        }
                    
                        // Для каждого периода суммируем по всем корням
                        let plan_per_period = [];
                        let actual_per_period = [];
                        
                        let all_roles = get_project_roles(frm).filter(r => r );
                        let rootTasks = Object.values(aggregatedTasks).filter(t => !t.parent_task);
                    
                        if ( rootTasks.length ) {
                            periods.forEach(period => {
                                let total_period_plan = 0;
                                let total_period_actual = 0;
                                rootTasks.forEach(root => {
                                    let planRoles = [...all_roles];
                                    let actualRoles = [...all_roles];
                                    //if ( !planRoles.length && !actualRoles.length ) return;
                                    let res = sumForTaskByPeriod(root.value, period, planRoles, actualRoles);
                                    total_period_plan += res.plan;
                                    total_period_actual += res.actual;
                                });
                                total_plan += total_period_plan;
                                total_actual += total_period_actual;
                            });
                        }
                        
                        let delta = total_plan ? (((total_actual - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                        
                        return `<div class="work-efforts-group">
                            ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                            <div class="we-group-actual"><span class="readonly-fact">${total_actual.toFixed(1)}</span></div>
                            ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat(delta).toFixed(1)}%</span></div>`}
                          </div>`;
                          
                    } else if ( cell.colIndex == 0 ) {
                        return __('Итого');
                    } else if ( cell.colIndex > 1 ) {
                        let parts = cell.column.id.split("_");
                        
                        if(parts.length == 3) {
                            let year = parts[1];
                            let month = parts[2];
                            let periods = get_display_periods(cur_frm, cur_frm.currentPeriodType || "month");
                            let aggregatedTasks = cur_frm.aggregatedTasks || {};
                        
                            let total_plan = 0;
                            let total_actual = 0;
                            
                            // Функция для рекурсивного подсчета данных за конкретный месяц
                            function calculateRoleDataMonthly(role, taskId, year, month, visited = new Set()) {
                                if (visited.has(taskId)) return { plan: 0, actual: 0 };
                                visited.add(taskId);
                                
                                let task = aggregatedTasks[taskId];
                                if (!task) return { plan: 0, actual: 0 };
                                
                                let roleEntry = task.role_data.find(r => r.role === role);
                                
                                // Считаем данные самой задачи для данной роли
                                let taskPlan = 0;
                                let taskActual = 0;
                                
                                if (roleEntry) {
                                    let planKey = `plan_${year}_${month}`;
                                    let forecastKey = `forecast_${year}_${month}`;
                                    let factKey = `fact_${year}_${month}`;
                                    
                                    taskPlan = parseFloat(roleEntry[planKey]) || 0;
                                    let period = periods.find(p => p.year == year && p.month == month);
                                    if (period.is_past) {
                                        taskActual = parseFloat(roleEntry[factKey]) || 0;
                                    } else {
                                        taskActual = parseFloat(roleEntry[forecastKey]) || 0;
                                    }
                                }
                                
                                // КРИТИЧЕСКОЕ ПРАВИЛО: Если у задачи есть данные для этой роли - используем ТОЛЬКО их
                                if (taskPlan > 0 || taskActual > 0) {
                                    return {
                                        plan: taskPlan,
                                        actual: taskActual
                                    };
                                }
                                
                                // Если у задачи нет данных для этой роли - суммируем данные дочерних задач
                                let childTasks = Object.values(aggregatedTasks).filter(t => t.parent_task === taskId);
                                let childrenData = { plan: 0, actual: 0 };
                                
                                childTasks.forEach(childTask => {
                                    let childData = calculateRoleDataMonthly(role, childTask.value, year, month, visited);
                                    childrenData.plan += childData.plan;
                                    childrenData.actual += childData.actual;
                                });
                                
                                return childrenData;
                            }
                            
                            // Для каждой роли находим корневые задачи и считаем данные
                            let allRoles = new Set();
                            Object.values(aggregatedTasks).forEach(task => {
                                task.role_data.forEach(roleEntry => {
                                    if (roleEntry.role) allRoles.add(roleEntry.role);
                                });
                            });
                            
                            allRoles.forEach(role => {
                                // ИСПРАВЛЕНИЕ: Используем тот же подход, что и в calculateRoleData
                                // Находим ВСЕ корневые задачи (без parent_task)
                                let rootTasks = Object.values(aggregatedTasks).filter(task => 
                                    !task.parent_task
                                );
                                
                                // Для каждой корневой задачи считаем данные для текущей роли
                                rootTasks.forEach(rootTask => {
                                    let data = calculateRoleDataMonthly(role, rootTask.value, year, month);
                                    total_plan += data.plan;
                                    total_actual += data.actual;
                                });
                            });
                        
                            let delta = total_plan ? (((total_actual - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                            
                            return `<div class="work-efforts-group"
                                data-year="${year}" 
                                data-month="${month}">
                                ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                                <div class="we-group-actual"><span class="readonly-fact">${total_actual.toFixed(1)}</span></div>
                                ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat( delta ).toFixed(1)}%</span></div>`}
                              </div>`;
                        }
                    }
                    return "";
                }
            }
        });

        load_work_efforts_data(frm, selectedPeriodType, selectedUnit);
    }
    init_table();
    frm.last_loaded_project = frm.doc.name;
    frm.last_loaded_time = new Date();
}


