function get_project_roles(frm) {
    let roles = [];
    if (frm.doc.custom_ts_details) {
        roles = frm.doc.custom_ts_details.map((x) => x.pt_role );
    }
    roles.push("");
    return Array.from( new Set(roles));
}

function get_display_periods(frm, periodType) {
    let periods = [];
    let month_start = frappe.datetime.month_start();
    let start_date = frm.doc.expected_start_date ? frm.doc.expected_start_date : month_start;
    let start = frappe.datetime.str_to_obj(start_date);
    let end_date = frm.doc.expected_end_date ? frm.doc.expected_end_date : frappe.datetime.add_months(start, 12);
    let end = frappe.datetime.str_to_obj(end_date);

    if (periodType === "month") {
        let current = start;
        while (frappe.datetime.obj_to_str(current) <= frappe.datetime.obj_to_str(end)) {
            let year = current.getFullYear();
            let i = current.getMonth();
            let is_past = ( frm.view_options == __("Прогноз и факт") ) 
                ? frappe.datetime.obj_to_str(current) < month_start
                : ( frm.view_options == __("Только факт") );
            periods.push({ year: year, month: i + 1, is_past: is_past });
            current = frappe.datetime.str_to_obj( frappe.datetime.add_months(current, 1) );
        }
    }
    return periods;
}

function updateTable(frm, periodType, unit) {
    let visibleRows =  frm.work_efforts_dt.bodyRenderer.visibleRowIndices;
    
    frm.work_efforts_dt.refresh(
        Object.values(frm.aggregatedTasks),
        get_columns_definition(frm, periodType, unit)
    );
    
    frm.work_efforts_dt.rowmanager.collapseAllNodes();
    frm.work_efforts_dt.rowmanager.showRows(visibleRows);
    cur_frm.work_efforts_dt.bodyScrollable.dispatchEvent(new CustomEvent('scroll'));
}

/**
 * Загрузка данных для таблицы «Трудозатраты»
 *
 * Здесь необходимо объединить данные:
 * – иерархии задач (с использованием whitelisted‑метода custom_task_get_children),
 * – данных из DocType "Project Work Efforts" (плановые и прогнозные данные),
 * – фактических данных из "User Timesheet Position".
 */
function load_work_efforts_data(frm, periodType, unit, updateRows) {
    // Массив для итоговых данных таблицы
    let table_data = [];
    let aggregatedTasks = {};

    // Получаем иерархию задач проекта через вызов метода custom_task_get_children.
    // Для начального уровня parent – пустая строка.
    frappe.call({
        method: "custom_task_get_children",
        args: {
            project: frm.doc.name,
            is_root: true,
            is_all: true
        },
        callback: function(r) {
            if (r.message) {
                // r.message – массив объектов с полями: value, title, expandable, parent_task, type, status.
                let tasks = r.message;
                let results = [];
                let parents = [];

                let addResults = function(results, parents, tasks, curNode) {
                    let parent = curNode.parent_task || "";

                    if ( !parents.includes( parent ) ) {
                        parents.push( parent );
                        let parentNode = tasks.filter((node) => ( node.value == parent ) )[0];

                        if (parentNode) {
                            addResults( results, parents, tasks, parentNode );
                        }

                        if (parentNode || !parent) {
                            let parentData = tasks.filter((node) => ( ( node.parent_task || "" ) == parent && !node.is_milestone ) );
                            results[ ( parent ? parent : "" ) ] = parentData;
                        }
                    }
                };

                for (const node of tasks) {
                    addResults( results, parents, tasks, node );
                }

                
                let periods = get_display_periods(frm, periodType);

                let saveData = function(tasks, level) {
                    if ( tasks ) {
                        tasks.forEach(function(task) {
                            if (!aggregatedTasks[task.value]) {
                                // Создаем базовую запись задачи и инициализируем пустой массив для данных по ролям
                                aggregatedTasks[task.value] = Object.assign({}, task);
                                aggregatedTasks[task.value].indent = level;
                                aggregatedTasks[task.value].role_data = [];
                            } else {
                                // Обновляем уровень indent, если требуется
                                aggregatedTasks[task.value].indent = level;
                            }
    
                            if( results[task.value] ) {
                                saveData(results[ task.value ],level+1);
                            }
                        });
                    }
                };
                
                saveData(results[""], 0);

                // Загружаем реальные данные из Project Work Efforts 
                frappe.db.get_list("Project Work Efforts", {
                    filters: { pwe_project: frm.doc.name },
                    fields: ["name", "pwe_task", "pwe_project_role"],
                    limit: 0
                }).then(pwe_list => {
                    let promises = pwe_list.map(pwe =>
                        frappe.db.get_doc("Project Work Efforts", pwe.name)
                    );
                    return Promise.all(promises);
                }).then(pwe_docs => {
                    
                    pwe_docs.forEach(doc => {
                        let task = doc.pwe_task;
                        let role = doc.pwe_project_role || "";
                        if (aggregatedTasks[task]) {
                            // Ищем запись для данной роли в role_data
                            let roleEntry = aggregatedTasks[task].role_data.find(r => r.role === role);
                            if (!roleEntry) {
                                roleEntry = { role: role };
                                aggregatedTasks[task].role_data.push(roleEntry);
                            }
                            // Для каждого периода из дочерней таблицы заполняем данные
                            if (doc.pwe_amount && doc.pwe_amount.length > 0) {
                                doc.pwe_amount.forEach(line => {
                                    let key = `plan_${line.pwea_year}_${line.pwea_month}`;
                                    let key2 = `forecast_${line.pwea_year}_${line.pwea_month}`;
                                    roleEntry[key] = line.pwea_plan || 0;
                                    roleEntry[key2] = line.pwea_expected || 0;
                                });
                            }
                        }
                    });

                    // Обработка фактических данных из User Timesheet Position 
                    frappe.db.get_list("User Timesheet Position", {
                        filters: {
                            project: frm.doc.name,
                            status: "Согласовано",
                            document_type: "Task"
                        },
                        fields: ["name", "document_name", "project_role", "period", "all_hours"],
                        limit: 0
                    }).then(ts_list => {
                        ts_list.forEach(ts => {
                            let parts = ts.period.split("-");
                            if(parts.length >= 2) {
                                let year = parts[0];
                                let month = parts[1];
                                let role = ts.project_role || "";
                                let task = ts.document_name; // Предполагается, что document_name соответствует task.value
                                
                                if (aggregatedTasks[task]) {
                                    // Ищем запись для данной роли
                                    let roleEntry = aggregatedTasks[task].role_data.find(r => r.role === role);
                                    if (!roleEntry) {
                                        // Если такой записи нет, попробуем обновить запись с пустой ролью, если у неё нет плановых/прогнозных данных
                                        let blankEntry = aggregatedTasks[task].role_data.find(r => !r.role || r.role.trim()==="");
                                        let entryValues = Object.values( blankEntry || [] ).find(r => String(r).trim()!="" && String(r).trim()!=0 );
                                        if (blankEntry && !entryValues) {
                                            blankEntry.role = role;
                                            roleEntry = blankEntry;
                                        } else {
                                            // Иначе создаем новую запись
                                            roleEntry = { role: role };
                                            aggregatedTasks[task].role_data.push(roleEntry);
                                        }
                                    }
                                    // Суммируем фактические часы
                                    let factKey = `fact_${year}_${flt(month)}`;
                                    roleEntry[factKey] = (roleEntry[factKey] || 0) + flt(ts.all_hours);
                                    // Сохраняем UTP name
                                    let factUTPs = `fact_utps_${year}_${flt(month)}`;
                                    if (!roleEntry[factUTPs]) {
                                        roleEntry[factUTPs] = [];
                                    }
                                    roleEntry[factUTPs].push(ts.name);
                                }
                            }
                        });

                        // Удаляем из каждой задачи все записи с пустой ролью
                        Object.values(aggregatedTasks).forEach(task => {
                            task.role_data = (task.role_data || [])
                                .filter(r => r.role && r.role.trim() !== "");
                        });
                        
                        rollup_fact_data(aggregatedTasks);
                        
                        // Преобразуем агрегированные задачи в массив
                        cur_frm.aggregatedTasks = aggregatedTasks;
                        let table_data = Object.values(aggregatedTasks);
                        
                        let visibleRows;
                        if (updateRows) {
                            visibleRows =  frm.work_efforts_dt.bodyRenderer.visibleRowIndices;
                        }
                        
                        frm.work_efforts_dt.refresh(table_data);
                        frm.work_efforts_dt.rowmanager.collapseAllNodes();
                        
                        if ( visibleRows ) {    
                            frm.work_efforts_dt.rowmanager.showRows(visibleRows);
                        }
                    }).catch(err => {
                        frappe.msgprint(__("Ошибка при загрузке данных User Timesheet Position"));
                        console.error(err);
                    }).finally(() => {
                        setCellStyles();
                        render_labour_percentage_chart( frm );
                        render_work_efforts_chart(frm);
                        updateTaskDimension(frm);
                    });
                }).catch(err => {
                    frappe.msgprint(__("Ошибка при загрузке данных Project Work Efforts"));
                    console.error(err);
                });
            }
        }
    });
}

//Функция для "свертывания" (rollup) фактических данных:
//для каждой задачи суммируются фактические трудозатраты (fact_*) из всех дочерних задач с той же ролью.
function rollup_fact_data(aggregatedTasks) {
    // Получаем массив задач, отсортированный по убыванию indent (то есть от самых глубоких к родительским)
    let tasksArray = Object.values(aggregatedTasks).sort((a, b) => b.indent - a.indent);
    tasksArray.forEach(child => {
        if (child.parent_task && aggregatedTasks[child.parent_task]) {
            let parent = aggregatedTasks[child.parent_task];
            // Для каждой записи по роли в дочерней задаче
            child.role_data.forEach(childRoleEntry => {
                let role = childRoleEntry.role;
                // Ищем в родительской задаче запись для той же роли
                let parentRoleEntry = parent.role_data.find(r => r.role === role);
                // Перебираем все свойства, начинающиеся с "fact_"
                for (let prop in childRoleEntry) {
                    if (prop.startsWith("fact_")) {
                        if (!parentRoleEntry) {
                            parentRoleEntry = { role: role };
                            parent.role_data.push(parentRoleEntry);
                        }
                        if (prop.startsWith("fact_utps")) {
                            if ( !parentRoleEntry[prop] ) {
                                parentRoleEntry[prop] = [];
                            }
                            parentRoleEntry[prop].push(...(childRoleEntry[prop] || [] ));
                        } else {
                            let childFact = parseFloat(childRoleEntry[prop]) || 0;
                            if (childFact) {
                                parentRoleEntry[prop] = (parseFloat(parentRoleEntry[prop]) || 0) + childFact;
                            }
                        }
                    }
                }
            });
        }
    });
}

