/**
 * Формирование описания колонок таблицы
 */
function get_columns_definition(frm, periodType, unit) {
    let columns = [];
    let allRoles = get_project_roles(frm);

    // 1. Колонка "Задачи" с иерархической структурой.
    columns.push({
        name: __("Задачи"),
        id: "subject",
        width: 250,
        sortable: false,
        dropdown: false,
        editable: false,
        focusable: false,
        //sticky: true,
        treeView: true
    });

    // 2. Колонка "Роли"
    columns.push({
        name: "Роли",
        id: "role",
        width: 220,
        sortable: false,
        editable: false,
        focusable: false,
        //sticky: true,
        dropdown: false,
        format: (value, row, column, data) => {
            let roleLines = "";
            
            if ( data ) {
                let role_data = data.role_data || [];
                role_data = role_data.sort((a, b) => (a.role.localeCompare(b.role)) );
                role_data.forEach(r => {
                    // Если роль не выбрана — пропускаем
                    //if (!r.role) {
                    //    return;
                    //}
                    roleLines += `<div>`;
                    roleLines += r.role ? __(r.role) : "-";
                    // Delete Button in Roles Column 
                    // Не показываем кнопку, если роль пуста или если для этой роли уже есть фактические данные
                    let hasFact = false;
                    for (const key in r) {
                        if (key.startsWith("fact_") && parseFloat(r[key]) > 0) {
                            hasFact = true;
                            break;
                        }
                    }
                    if (r.role && !hasFact) {
                        roleLines += `<button data-task="${data.value}" data-role="${r.role}"
                        class="btn delete-role-btn btn-default btn-sm filter-x-button" title="Удалить роль">
    					<span class="filter-icon">
    						<svg class="es-icon es-line  icon-sm" style="" aria-hidden="true">
                		    	<use class="" href="#es-small-close"></use>
                		    </svg>
    					</span>
    				</button>`;
                    }
                    roleLines += `</div>`;
                });
                // Добавление выпадающего списка с новыми ролями
                // Вычисляем доступные роли, которых еще нет в role_data
                let existingRoles = role_data.map(r => r.role);
                let availableRoles = allRoles.filter(r => r && !existingRoles.includes(r));
                if (availableRoles.length > 0) {
                    roleLines += `<div>
                        <select class="new-role-select btn btn-default"" data-task="${data.value}"> 
                            <option value="">${__("Добавить роль")}</option>`;
                    availableRoles.forEach(role => {
                        roleLines += `<option value="${role}">${__(role)}</option>`;
                    });
                    roleLines += `</select>
                        </div>`;
                }
            } else if ( value ) {
                lines = value;
            }
            
            return roleLines;
        }
    });
    
    /*
       Вместо вложенных columns формируем одну колонку, внутри которой вручную выводим три значения.
       Для редактирования (если период текущий или будущий) мы делаем значение "факт/прогноз" кликабельным.
    */
    let periods = get_display_periods(frm, periodType);
    periods.forEach(function(period) {
        // Вычисляем: если период в прошлом – отображаем "факт", иначе "прогноз"
        let subcolumn_label = period.is_past ? __("Факт") : __("Прогноз");
        columns.push({
            //name: period.year + " " + period.month,
            name: `<div style="text-align:center;">
                    ${period.year} ${period.month}<br/>
                    <div class="work-efforts-group-header">` +
                        (cur_frm.hide_plan ? "" : `<span>План</span>`) +
                        `<span>${subcolumn_label}</span>` +
                        (cur_frm.hide_delta ? "" : `<span>Δ</span>`) +
                    `</div>
               </div>`,
            id: `group_${period.year}_${period.month}`,
            sortable: false,
            get width() {
                return 200 - (cur_frm.hide_plan ? 65 : 0 ) - (cur_frm.hide_delta ? 65 : 0);
            },
            dropdown: false,
            focusable: false,
            editable: false,
            format: function(value, row, column, data) {
                let lines = "";
                
                if ( data ) {
                    let role_data = data.role_data || [];
                    role_data = role_data.sort((a, b) => (a.role.localeCompare(b.role)) );
    
                    role_data.forEach(function(r) {
                        let plan = r[`plan_${period.year}_${period.month}`] || 0;
                        let actual = period.is_past
                                     ? (r[`fact_${period.year}_${period.month}`] || 0)
                                     : (r[`forecast_${period.year}_${period.month}`] || 0);
                        let delta = plan ? (((actual - plan) / plan) * 100).toFixed(1) : 0;
                        lines += `<div class="work-efforts-group" 
                                    data-year="${period.year}" 
                                    data-month="${period.month}"
                                    data-task="${data.value}"
                                    data-role="${r.role || ''}">
                                    ${cur_frm.hide_plan ? "" : `<div class="we-group-plan${plan==0?" zero":""}"><span>${plan}</span></div>`}
                                    <div class="we-group-actual${actual==0?" zero":""}"><span class="${ period.is_past ? "readonly-fact" : "editable-forecast" }">${actual}</span></div>
                                    ${cur_frm.hide_delta ? "" : `<div class="we-group-delta${delta==0?" zero":""}"><span>${delta}%</span></div>`}
                                  </div>`;
                    });
                } else if ( value ) {
                    lines = value;
                }
                return lines;
            }
        });
    });
    
    // Добавляем колонку "Итого" – суммарные значения по всем периодам
    columns.push({
        name: `<div style="text-align:center;">
                    ${__("Итого")}<br/>
                    <div class="work-efforts-group-header">` +
                        (cur_frm.hide_plan ? "" : `<span>План</span>`) +
                        `<span>${__("Прогноз")}</span>` +
                        (cur_frm.hide_delta ? "" : `<span>Δ</span>`) +
                    `</div>
               </div>`,
        id: "total",
        get width() {
                return 200 - (cur_frm.hide_plan ? 65 : 0 ) - (cur_frm.hide_delta ? 65 : 0);
            },
        sortable: false,
        dropdown: false,
        focusable: false,
        editable: false,
        format: function(value, row, column, data) {
            let lines = "";
            
            if (data) {
                let role_data = data.role_data || [];
                role_data = role_data.sort((a, b) => (a.role.localeCompare(b.role)) );
    
                role_data.forEach(function(r) {
                    let total_plan = 0, total_forecast = 0;
                    
                    periods.forEach(function(period) {
                        let p = parseFloat(r[`plan_${period.year}_${period.month}`]) || 0;
                        total_plan += p;
                        if (period.is_past) {
                            let f = parseFloat(r[`fact_${period.year}_${period.month}`]) || 0;
                            total_forecast += f;
                        } else {
                            let f = parseFloat(r[`forecast_${period.year}_${period.month}`]) || 0;
                            total_forecast += f;
                        }
                    });
                    let delta = total_plan ? (((total_forecast - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                     lines += `<div class="work-efforts-group" 
                            data-task="${data.value}"
                            data-role="${r.role || ''}">
                            ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                            <div class="we-group-actual"><span class="readonly-fact">${total_forecast.toFixed(1)}</span></div>
                            ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat(delta).toFixed(1)}%</span></div>`}
                          </div>`;
                });
            }else if ( value ) {
                lines = value;
            }
                    
            return lines;
        }
    });

    return columns;
}

// Обработчик для выбора новой роли из выпадающего списка
$(document).on('change', '.new-role-select', function(e) {
    let newRole = $(this).val();
    if (!newRole) return;
    let task = $(this).data('task');
    let rowIndex = $(this).closest(".dt-cell").data("row-index");
    // Получаем агрегированные данные из cur_frm
    let aggregatedTasks = cur_frm.aggregatedTasks || {};
    if (aggregatedTasks[task]) {
        // Добавляем новую запись в role_data, если такой роли еще нет
        let exists = aggregatedTasks[task].role_data.some(r => r.role === newRole);
        if (!exists) {
            aggregatedTasks[task].role_data.push({ role: newRole });
        }
        // После выбора новой роли – перезагружаем таблицу
        updateTable(cur_frm, "month", "hours");
    }
});

// Обработчик для удаления роли
$(document).on('click', '.delete-role-btn', function(e) {
    e.stopPropagation();
    let btn = $(this);
    let task = btn.data("task");
    let role = btn.data("role");
    let rowIndex = btn.closest(".dt-cell").data("row-index");
    frappe.confirm(
        __("Вы действительно хотите удалить роль {0} для задачи {1}?", [role, task]),
