        .data('original-value', currentValue);

    $span.html($input);
    $input.focus();
});

/* Функция расчёта суммы прогнозных трудозатрат у дочерних задач */
function get_child_budget_sum(account, dimension, period, aggregatedBudget) {
    let sum = 0;
    Object.values(aggregatedBudget).forEach(child => {
        if (child.parent_account === account) {
            // Для данного дочернего элемента ищем запись по роли
            let childDimEntry = (child.dimension_data || [])[0];//.find(r => r.role === role);
            let forecastKey = `forecast_${period.year}_${period.month}`;
            let childForecast = childDimEntry ? parseFloat(childDimEntry[forecastKey]) || 0 : 0;
            if (childForecast > 0) {
                sum += childForecast;
            } else {
                // Если прямые данные отсутствуют, пробуем рекурсивно получить сумму из его потомков
                sum += get_child_budget_sum(child.value, dimension, period, aggregatedBudget);
            }
        }
    });
    return sum;
}

/* Функция для определения максимального допустимого значения в дочерней статье */
function get_parent_budget_limit(account, dimension, period, aggregatedBudget) {
    // Начинаем с непосредственного родителя текущей задачи
    let currentAccount = aggregatedBudget[account];
    let excluded = [];
    while (currentAccount && currentAccount.parent_account) {
        excluded.push( currentAccount.value );
        let parent = aggregatedBudget[currentAccount.parent_account];
        if (parent) {
            let parentDimEntry = (parent.dimension_data || [])[0];//.find(r => r.role === role);
            let forecastKey = `forecast_${period.year}_${period.month}`;
            let parentForecast = parentDimEntry ? parseFloat(parentDimEntry[forecastKey]) || 0 : 0;
            if (parentForecast > 0) {
                // Суммируем прогнозные трудозатраты для всех детей родителя (за исключением текущей ветки)
                let siblingsSum = get_child_budget_sum(
                    parent.value, 
                    dimension, 
                    period, 
                    Object.values(aggregatedBudget).filter( function( el ) { return excluded.indexOf( el.value ) < 0; } )
                );
                let maxAllowed = parentForecast - siblingsSum;
                return maxAllowed;
            }
        }
        currentAccount = parent; // поднимаемся вверх по дереву
    }
    return null;
}

// При потере фокуса input – сохраняем значение
$(document).on('blur', '.bg-edit-input', function(e) {
    let $input = $(this);
    let new_value = parseFloat($input.val());

    let original_value = $input.data('original-value');
    if (new_value == original_value) {
        // Если значение не изменилось, восстанавливаем исходное отображение и выходим
        $input.parent().text( numberformat( original_value ) );
        return;
    }
    
    let $group = $input.closest('.budget-group');
    let year = $group.data('year');
    let month = $group.data('month');
    let period = { year: year, month: month };
    let account = $group.data('account');
    let task = $group.data('task');
    /*let dim_type = $group.data('dimension-type');
    let dim_name = $group.data('dimension-name');
    let dim_title = $group.data('dimension-title');/**/
    let dimension = task ? [ { doc:"Task", docname:task } ] : null;
    
    // Получаем агрегированные данные
    let aggregatedBudget = cur_frm.aggregatedBudget || {};
    
    // Определяем, является ли текущая статья родительской (есть ли дочерние статьи)
    let isParent = Object.values(aggregatedBudget).some(t => t.parent_account === account);
    if (isParent) {
        // В родительской статье: новое значение не должно быть меньше суммы прогнозов у дочерних задач
        let childrenSum = get_child_budget_sum(account, dimension, period, aggregatedBudget);
        if (new_value < childrenSum) {
            frappe.msgprint(__("Значение не может быть меньше суммы по дочерним статьям (" + childrenSum + ")"));
            $input.addClass("error");
            return;
        }
    }
    
    // В дочерней: максимальное значение ограничено так, чтобы у родительской статьи (или ближайшей с заданным прогнозом) сумма всех дочерних не превышала прогноз родителя
    let parentLimit = get_parent_budget_limit(account, dimension, period, aggregatedBudget);
    if (parentLimit !== null && (new_value > parentLimit) ) {
        frappe.msgprint(__("Значение не может превышать " + parentLimit + " (ограничение родительской статьи)"));
        $input.addClass("error");
        return;
    }
    
    // Восстанавливаем отображение: заменяем input на span с новым значением
    $input.parent().text( numberformat( new_value ) );
    // Вызываем функцию обновления прогнозного значения на сервере
    updateBudgetValue( cur_frm.doc.name, account, dimension, year, month, new_value );
});/**/

