function compute_time_data(frm) {
    const start = frm.doc.expected_start_date;
    const end = frm.doc.expected_end_date;
    if (!start || !end) return { percent: 0, details: __("Даты не заданы") };

    const s = new Date(start).getTime();
    const e = new Date(end).getTime();
    const today = new Date().getTime();

    const totalDays = (e - s) / (1000 * 60 * 60 * 24);
    const elapsedDays = (today - s) / (1000 * 60 * 60 * 24);
    
    let pct = 0;
    if (totalDays > 0) pct = (elapsedDays / totalDays) * 100;
    if (today < s) pct = 0;
    if (today > e) pct = 100;
    
    pct = Math.round(pct * 100) / 100;
    return { 
        percent: pct, 
        details: __("План") + ": " + frappe.datetime.str_to_user(end) + "<br>" + __("Прошло") + ": " + Math.max(0, Math.floor(elapsedDays)) + " " + __("дн.")
    };
}

function get_labour_data(frm) {
    // Симуляция получения данных, т.к. функции _get_plant_fact_efforts нет в контексте
    // Попробуем найти агрегированные данные в форме, если они есть
    let plan = 0, fact = 0;
    
    // Fallback (или используйте ваши глобальные функции, если они доступны)
    try {
        if(typeof _get_plant_fact_efforts === 'function') {
            let vals = _get_plant_fact_efforts(frm);
            plan = vals.plan; fact = vals.fact;
        }
    } catch(e) {}

    let pct = 0;
    if (plan > 0) pct = (fact / plan) * 100;
    else if (fact > 0) pct = 100;
    
    return { 
        percent: Math.round(pct*100)/100, 
        details: __("План") + ": " + plan + " " + __("ч.") + "<br>" + __("Факт") + ": " + fact + __("ч.") 
    };
}

function get_revenue_data(frm) {
    let plan = 0, fact = 0;
    try {
        if(typeof _get_revenue_values === 'function') {
            let vals = _get_revenue_values(frm);
            plan = vals.planned; fact = vals.actual;
        }
    } catch(e) {}

    let pct = 0;
    if (plan > 0) pct = (fact / plan) * 100;
    
    return { 
        percent: Math.round(pct*100)/100, 
        details: __("План") + ": " + format_currency(plan) + "<br>" + __("Факт") + ": " + format_currency(fact) 
    };
}

